/* Istiqama — Application locale sans serveur, version 1 */
'use strict';
const PRAYERS=['Fajr','Dhuhr','Asr','Maghrib','Isha'];
const ALL_TIMES=['Fajr','Chourouk','Dhuhr','Asr','Maghrib','Isha'];
const MONTHS=['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'];
const WEEK=['L','M','M','J','V','S','D'];
const BASE=[{id:'prayers',name:'Prières',category:'religion',type:'prayers',unit:'prières'}, {id:'quranPages',name:'Coran',category:'religion',type:'number',unit:'pages'}, {id:'istighfar',name:'Istighfar',category:'religion',type:'counter',unit:'répétitions'}, {id:'dhikr',name:'Dhikr',category:'religion',type:'counter',unit:'répétitions'}, {id:'siwak',name:'Siwak',category:'habits',type:'counter',unit:'utilisations'}, {id:'nigelle',name:'Huile de nigelle',category:'habits',type:'boolean',unit:'jours'}, {id:'floss',name:'Fil dentaire',category:'habits',type:'boolean',unit:'jours'}];
const DEFAULTS={version:1,createdAt:'',savedAt:'',days:{},customHabits:[],prayerTimes:{},settings:{mosque:'Mosquée EN-NASR — Saint-Priest',quranTotal:711,quranCurrentPage:0,lastExportAt:null,reminders:true}};
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>JSON.parse(JSON.stringify(v));
const isObj=v=>!!v&&typeof v==='object'&&!Array.isArray(v);
const pad=n=>String(n).padStart(2,'0');
function today(){const d=new Date();return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`}
function dayOffset(date,n){let d=new Date(`${date}T12:00:00`);d.setDate(d.getDate()+n);return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`}
function displayDate(s){let d=new Date(`${s}T12:00:00`);return Number.isFinite(d.getTime())?d.toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'}):s}
function isDate(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s||''))return false;const d=new Date(`${s}T12:00:00`);return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===s}
function validTime(t){return typeof t==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(t)}
function num(v){const n=Number(v);return Number.isFinite(n)?Math.max(0,Math.floor(n)):0}
const number=v=>new Intl.NumberFormat('fr-FR').format(num(v));
function ico(n,size=21){const paths={house:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',religion:'<path d="M20 15A8 8 0 0 1 9 4 8 8 0 1 0 20 15Z"/><path d="m17 3 .7 2.3L20 6l-2.3.7L17 9l-.7-2.3L14 6l2.3-.7z"/>',habits:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="m7 12 3 3 7-7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',chart:'<path d="M3 3v18h18M7 17v-5M12 17V8M17 17V5"/>',book:'<path d="M12 6C9 4 6 4 3 5v14c3-1 6-1 9 1 3-2 6-2 9-1V5c-3-1-6-1-9 1zM12 6v14"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',edit:'<path d="M12 20h9M16 4l4 4-11 11H5v-4L16 4z"/>',back:'<path d="m15 18-6-6 6-6"/>',forward:'<path d="m9 18 6-6-6-6"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',upload:'<path d="M12 21V9m-4 4 4-4 4 4M4 7V3h16v4"/>',check:'<path d="m4 12 5 5L20 6"/>',close:'<path d="M5 5l14 14M19 5 5 19"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 8-3 8h18s-3-1-3-8ZM10 20a2 2 0 0 0 4 0"/>',trophy:'<path d="M8 3h8v7a4 4 0 0 1-8 0V3ZM8 5H4v3a4 4 0 0 0 4 4M16 5h4v3a4 4 0 0 1-4 4M12 14v4M8 21h8M9 18h6"/>',shield:'<path d="M12 2 4 5v6c0 5 3 8 8 11 5-3 8-6 8-11V5l-8-3Z"/><path d="m8 12 3 3 5-6"/>',gear:'<circle cx="12" cy="12" r="3"/><path d="m12 2 2 2 3-.5.5 3L20 8l-1 4 1 4-2.5 1.5-.5 3-3-.5-2 2-2-2-3 .5-.5-3L4 16l1-4-1-4 2.5-1.5.5-3L10 4z"/>',archive:'<rect x="3" y="4" width="18" height="4" rx="1"/><path d="M5 8v12h14V8M10 13h4"/>',trash:'<path d="M4 7h16M10 4h4M6 7l1 14h10l1-14M10 11v7M14 11v7"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7M12 7h.01"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.info}</svg>`}
let state=null;let db=null;let queue=Promise.resolve();let tab='home',editDate=today(),manualDate=today(),calendarYear=Number(today().slice(0,4)),calendarMonth=Number(today().slice(5,7))-1,calendarView='month',calendarMode='one',calendarHabit='prayers',reportView='month',reportMetric='prayers',reportYear=Number(today().slice(0,4)),reportMonth=Number(today().slice(5,7))-1,expandedPrayer=null;let modal=null,pendingMerge=null,toastTimer;
async function openDB(){if(!('indexedDB'in window))return null;return new Promise(resolve=>{try{let req=indexedDB.open('istiqama-db',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('storage'))req.result.createObjectStore('storage')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null)}catch(e){resolve(null)}})}
async function readStorage(){if(db)return new Promise(resolve=>{try{let tx=db.transaction('storage','readonly'),r=tx.objectStore('storage').get('current');r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>resolve(null)}catch(e){resolve(null)}});try{return JSON.parse(localStorage.getItem('istiqama-state')||'null')}catch(e){return null}}
async function writeStorage(snapshot){if(db)return new Promise((resolve,reject)=>{try{let tx=db.transaction('storage','readwrite');tx.objectStore('storage').put(snapshot,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)}catch(e){reject(e)}});localStorage.setItem('istiqama-state',JSON.stringify(snapshot))}
function save(){state.savedAt=new Date().toISOString();const snapshot=clone(state);queue=queue.catch(()=>{}).then(()=>writeStorage(snapshot)).catch(err=>{console.error('Erreur sauvegarde locale',err);toast('Sauvegarde locale impossible : exporte tes données.')})}
function getDay(date){return state.days[date]||{}}
function mutableDay(date){return state.days[date]||(state.days[date]={})}
function allHabits(){return BASE.concat(state.customHabits.map(h=>({...h,id:'custom:'+h.id}))) }
function habitById(id){return allHabits().find(h=>h.id===id)}
function getVal(day,h){if(!day)return 0;if(h.id==='prayers')return PRAYERS.reduce((a,p)=>a+(day.prayers?.[p]?.status?1:0),0);if(h.id.startsWith('custom:')){const v=day.custom?.[h.id.slice(7)];return h.type==='boolean'?(v===true?1:0):num(v)}return h.type==='boolean'?(day[h.id]===true?1:0):num(day[h.id])}
function hasVal(date,h){return getVal(getDay(date),h)>0}
function intensity(h,v){if(!v)return 0;if(h.type==='boolean')return 3;if(h.id==='prayers')return v>=5?3:v>=3?2:1;if(h.id==='siwak')return Math.min(3,v);if(h.id==='quranPages')return v>=10?3:v>=5?2:1;if(h.id==='dhikr'||h.id==='istighfar')return v>=100?3:v>=33?2:1;return v>=10?3:v>=3?2:1}
function changeValue(id,value,date=editDate){let h=habitById(id);if(!h)return;let d=mutableDay(date),v=h.type==='boolean'?!!value:num(value);if(id.startsWith('custom:')){d.custom||=( {} );if(v)d.custom[id.slice(7)]=v;else delete d.custom[id.slice(7)]}else if(v)d[id]=v;else delete d[id];save();render()}
function nudge(id,n,date=editDate){let h=habitById(id);if(!h)return;changeValue(id,getVal(getDay(date),h)+n,date)}
function touchPage(id,v){let d=mutableDay(editDate);if(id==='quranPosition'){let p=Math.min(num(v),num(state.settings.quranTotal));if(p)d.quranPosition=p;else delete d.quranPosition;if(editDate===today())state.settings.quranCurrentPage=p;save();render()}}
function prayerSet(prayer,field,value){let day=mutableDay(editDate);day.prayers||={};let p=day.prayers[prayer]||{};if(field==='status'&&!value){delete day.prayers[prayer];if(!Object.keys(day.prayers).length)delete day.prayers}else{if(value)p[field]=value;else delete p[field];day.prayers[prayer]=p}save();render()}
function currentTimes(date){return state.prayerTimes[date]||null}
function activeTime(rec,p){return rec?.times?.[p]||'—'}
function activeIqama(rec,p){return rec?.iqama?.[p]||null}
function showToast(t){toast(t)}
function toast(t){let el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000)}
function setTab(t,moveTop=true){tab=t;expandedPrayer=null;render(moveTop)}
function navHTML(){let nav=[['home','house','Accueil'],['religion','religion','Religion'],['habits','habits','Habitudes'],['calendar','calendar','Calendriers'],['reports','chart','Bilans']];return nav.map(([key,i,label])=>`<button class="nav-btn ${tab===key?'active':''}" aria-current="${tab===key?'page':'false'}" data-action="nav" data-tab="${key}">${ico(i)}<span>${label}</span></button>`).join('')}
function dateControls(){return `<div class="date-controls"><button class="circle-btn" data-action="date-shift" data-delta="-1" aria-label="Jour précédent">${ico('back',17)}</button><div class="selected-date"><button class="date-jump" data-action="pick-day">${esc(displayDate(editDate))}</button><div class="tiny">Clique sur la date pour la modifier</div></div><button class="circle-btn" data-action="date-shift" data-delta="1" aria-label="Jour suivant">${ico('forward',17)}</button></div>`}
function summary(d){const prayerCount=getVal(d,BASE[0]);const q=num(d.quranPages),siwak=num(d.siwak);const customDone=state.customHabits.filter(h=>!h.archived&&getVal(d,{...h,id:'custom:'+h.id})>0).length;const total=allHabits().filter(h=>!h.archived).length;const done=allHabits().filter(h=>!h.archived&&getVal(d,h)>0).length;return {prayerCount,q,siwak,customDone,done,total}}
function remindersHtml(){if(!state.settings.reminders)return '';const d=getDay(today());const notices=[];if(!num(d.quranPages))notices.push('Lecture du Coran non renseignée');if(d.nigelle!==true)notices.push('Prise de nigelle non renseignée');if(d.floss!==true)notices.push('Fil dentaire non renseigné');const last=state.settings.lastExportAt?new Date(state.settings.lastExportAt):null;const age=last?Math.floor((Date.now()-last.getTime())/86400000):null;if(age===null||age>=7)notices.push(age===null?'Pense à exporter une première sauvegarde':`Dernière sauvegarde il y a ${age} jours`);if(!notices.length)return '';return `<div class="card subtle"><div class="split"><strong>${ico('bell',17)} Rappels</strong><span class="pill neutral">Dans l’app seulement</span></div><div class="stack" style="margin-top:10px">${notices.map(x=>`<div class="tiny">• ${esc(x)}</div>`).join('')}</div></div>`}
function renderHome(){const d=getDay(today()),s=summary(d);const t=currentTimes(today());return `<p class="eyebrow2">TABLEAU DE BORD</p><h1 class="page-title">Mon quotidien</h1><p class="page-sub">${esc(displayDate(today()))}</p><div class="card highlight"><div class="split"><div><div class="fine">Suivis renseignés aujourd’hui</div><div class="big-number">${s.done}<span class="muted" style="font-size:17px"> / ${s.total}</span></div></div><span class="pill">${s.done} activité${s.done>1?'s':''}</span></div><p class="tiny" style="margin:10px 0 0">Les éléments non renseignés ne sont jamais considérés comme des échecs.</p></div><h2 class="h2">${ico('religion')} Religion</h2><div class="two-grid"><div class="metric"><div class="fine">Prières renseignées</div><div class="big-number">${s.prayerCount}<span class="muted" style="font-size:16px"> / 5</span></div><div class="tiny">${t?'Horaires de la mosquée':'Horaires indisponibles'}</div></div><div class="metric"><div class="fine">Coran aujourd’hui</div><div class="big-number">${s.q}</div><div class="tiny">pages lues · page ${num(state.settings.quranCurrentPage)}/${num(state.settings.quranTotal)}</div></div><div class="metric"><div class="fine">Istighfar</div><div class="big-number">${number(d.istighfar)}</div><div class="tiny">répétitions</div></div><div class="metric"><div class="fine">Dhikr</div><div class="big-number">${number(d.dhikr)}</div><div class="tiny">répétitions</div></div></div><div class="section-actions"><button class="quick-link" data-action="nav" data-tab="religion" style="width:100%"><span>${ico('religion',19)} &nbsp; Ouvrir Religion</span>${ico('forward',16)}</button></div><h2 class="h2">${ico('habits')} Habitudes</h2><div class="three-grid"><div class="metric"><div class="fine">Siwak</div><div class="big-number">${s.siwak}</div><div class="tiny">fois</div></div><div class="metric"><div class="fine">Nigelle</div><div class="big-number">${d.nigelle===true?'✓':'—'}</div><div class="tiny">${d.nigelle===true?'Renseigné':'Non renseigné'}</div></div><div class="metric"><div class="fine">Fil dentaire</div><div class="big-number">${d.floss===true?'✓':'—'}</div><div class="tiny">${d.floss===true?'Renseigné':'Non renseigné'}</div></div></div><div class="section-actions"><button class="quick-link" data-action="nav" data-tab="habits" style="width:100%"><span>${ico('habits',19)} &nbsp; Ouvrir Habitudes</span>${ico('forward',16)}</button></div>${remindersHtml()}<div class="two-grid"><button class="quick-link" data-action="nav" data-tab="calendar"><span>Calendriers</span>${ico('calendar')}</button><button class="quick-link" data-action="nav" data-tab="reports"><span>Bilans</span>${ico('chart')}</button></div><p class="footer-info">Istiqama · Sauvegarde privée sur cet appareil · Aucun compte requis</p>`}
function counterCard(id,label,unit){let h=habitById(id),v=getVal(getDay(editDate),h),btns=(id==='siwak'?[1,10,33,100]:[1,10,33,100]);return `<div class="card"><div class="split"><div><h3 class="h3">${esc(label)}</h3><div class="fine">${esc(unit)} enregistrées</div></div><div class="big-counter">${number(v)}</div></div><div class="btn-row" style="margin-top:14px">${btns.map(n=>`<button class="btn outline small" data-action="nudge" data-habit="${esc(id)}" data-value="${n}">+${n}</button>`).join('')}<button class="btn small" data-action="nudge" data-habit="${esc(id)}" data-value="-1">−1</button></div><div class="section-actions"><span class="fine">Saisie du total exact</span><button class="btn small" data-action="set-count" data-habit="${esc(id)}">${ico('edit',15)} Modifier</button></div></div>`}
function booleanRow(id,label,detail=''){let d=getDay(editDate),done=d[id]===true;return `<div class="toggle-row"><div><strong>${esc(label)}</strong>${detail?`<div class="fine">${esc(detail)}</div>`:''}</div><button class="switch ${done?'on':''}" data-action="toggle" data-habit="${esc(id)}" aria-pressed="${done}">${done?'✓':'—'}</button></div>`}
function customEntry(h){let id='custom:'+h.id,v=getVal(getDay(editDate),{...h,id});if(h.type==='boolean')return `<div class="toggle-row"><div><strong>${esc(h.name)}</strong><div class="fine">Habitude personnalisée</div></div><button class="switch ${v?'on':''}" data-action="toggle" data-habit="${esc(id)}" aria-pressed="${!!v}">${v?'✓':'—'}</button></div>`;return `<div class="counter-row"><div><strong>${esc(h.name)}</strong><div class="tiny">${esc(h.unit||'fois')}</div></div><div style="text-align:right"><div class="big-counter" style="font-size:23px">${number(v)}</div><div class="counter-buttons"><button class="btn outline small" data-action="nudge" data-habit="${esc(id)}" data-value="1">+1</button><button class="btn outline small" data-action="nudge" data-habit="${esc(id)}" data-value="10">+10</button><button class="btn small" data-action="set-count" data-habit="${esc(id)}">${ico('edit',13)}</button></div></div></div>`}
function customSection(category){let items=state.customHabits.filter(h=>h.category===category&&!h.archived);return `<h2 class="h2">Mes suivis personnalisés</h2><div class="card">${items.length?items.map(customEntry).join(''):'<p class="fine">Tu n’as pas encore ajouté d’habitude personnalisée à cette catégorie.</p>'}<button class="btn outline block" data-action="habit-add" data-category="${category}" style="margin-top:15px">${ico('plus',17)} Ajouter une habitude</button><button class="btn ghost block" data-action="manage-habits">Gérer mes habitudes</button></div>`}
function renderReligion(){let date=editDate,d=getDay(date),rec=currentTimes(date);const times=rec?.times||{};const src=rec?`<span class="pill ${rec.verified?'':'gold'}">${rec.verified?'Horaire confirmé':'Extrait à vérifier'}</span>`:'<span class="pill neutral">Horaires indisponibles</span>';return `<p class="eyebrow2">RELIGION</p><h1 class="page-title">Ma pratique</h1><p class="page-sub">Prières, lecture du Coran et répétitions quotidiennes.</p>${dateControls()}<div class="card"><div class="split"><h2 class="h3" style="margin:0">Prières de la journée</h2>${src}</div><div class="fine" style="margin-top:5px">${esc(state.settings.mosque)}</div>${!rec?'<div class="notice warning" style="margin-top:13px">Aucun horaire de la mosquée enregistré pour ce jour. Tu peux quand même renseigner tes prières.</div>':''}${PRAYERS.map(p=>{const performed=d.prayers?.[p]||{},status=performed.status,open=expandedPrayer===p;return `<div class="prayer-line"><div class="prayer-main"><div><div class="prayer-label">${p}</div><div class="time-aux">Prière : <span class="time">${esc(activeTime(rec,p))}</span>${activeIqama(rec,p)?` · Iqama : <span class="time">${esc(activeIqama(rec,p))}</span>`:' · Iqama non renseignée'}</div></div><button class="status ${status==='ontime'?'done':status==='late'?'late':''}" data-action="expand-prayer" data-prayer="${p}">${status==='ontime'?'À l’heure':status==='late'?'En retard':'Non renseignée'} ${open?'▲':'▾'}</button></div>${open?`<div class="prayer-expand"><div class="field"><label>Accomplissement</label><select data-change="prayer" data-prayer="${p}" data-field="status"><option value="" ${!status?'selected':''}>Non renseignée</option><option value="ontime" ${status==='ontime'?'selected':''}>À l’heure</option><option value="late" ${status==='late'?'selected':''}>En retard</option></select></div>${status?`<div class="subgrid"><div class="field"><label>Lieu</label><select data-change="prayer" data-prayer="${p}" data-field="place"><option value="">Non renseigné</option><option value="mosque" ${performed.place==='mosque'?'selected':''}>Mosquée</option><option value="home" ${performed.place==='home'?'selected':''}>Maison</option><option value="other" ${performed.place==='other'?'selected':''}>Autre</option></select></div><div class="field"><label>Mode</label><select data-change="prayer" data-prayer="${p}" data-field="group"><option value="">Non renseigné</option><option value="group" ${performed.group==='group'?'selected':''}>En groupe</option><option value="solo" ${performed.group==='solo'?'selected':''}>Seul</option></select></div></div><div class="field"><label>Heure réelle (facultative)</label><input type="time" value="${esc(performed.actual||'')}" data-change="prayer" data-prayer="${p}" data-field="actual"></div>`:'<p class="tiny">Choisis « À l’heure » ou « En retard » pour renseigner le lieu et le mode.</p>'}</div>`:''}</div>`}).join('')}${rec?.times?.Chourouk?`<p class="fine" style="margin-top:12px">Chourouq : ${esc(rec.times.Chourouk)} (information, pas une sixième prière)</p>`:''}${rec&&!rec.verified?'<p class="source-alert">Horaires retranscrits depuis la vidéo MAWAQIT. Vérification conseillée auprès de la mosquée.</p>':''}</div><h2 class="h2">${ico('book')} Lecture du Coran</h2><div class="card"><div class="two-grid"><div class="metric"><div class="fine">Pages lues ce jour</div><div class="big-number">${number(d.quranPages)}</div></div><div class="metric"><div class="fine">Page actuelle</div><div class="big-number">${number(state.settings.quranCurrentPage)}<span class="fine"> / ${num(state.settings.quranTotal)}</span></div></div></div><div class="field"><label>Nombre de pages lues pour cette date</label><input type="number" inputmode="numeric" min="0" max="10000" data-change="quran-pages" value="${num(d.quranPages)}"></div><div class="field"><label>Dernière page atteinte ce jour (1 à ${num(state.settings.quranTotal)})</label><input type="number" inputmode="numeric" min="0" max="${num(state.settings.quranTotal)}" data-change="quran-position" value="${d.quranPosition??(editDate===today()?state.settings.quranCurrentPage:'')}"></div><div class="fine">La progression actuelle ne recule pas quand tu corriges un ancien jour.</div><div class="section-actions"><div><strong>${number(totalFinished())}</strong> <span class="fine">lectures complètes enregistrées</span></div><button class="btn outline small" data-action="finish-quran">Lecture terminée</button></div></div><h2 class="h2">Compteurs</h2>${counterCard('istighfar','Istighfar','répétitions')}${counterCard('dhikr','Dhikr','répétitions')}${customSection('religion')}`}
function renderHabits(){return `<p class="eyebrow2">HABITUDES</p><h1 class="page-title">Mes habitudes</h1><p class="page-sub">Renseigne uniquement ce que tu as réellement effectué.</p>${dateControls()}${counterCard('siwak','Siwak','utilisations')}<div class="card"><h2 class="h3">Suivi quotidien</h2>${booleanRow('nigelle','Huile de nigelle','Prise du jour')}${booleanRow('floss','Fil dentaire','Utilisation du jour')}</div>${customSection('habits')}`}
function totalFinished(){return Object.values(state.days).reduce((a,d)=>a+num(d.quranFinished),0)}
function monthTitle(y,m){return `${MONTHS[m].charAt(0).toUpperCase()+MONTHS[m].slice(1)} ${y}`}
function mkDate(y,m,d){return `${y}-${pad(m+1)}-${pad(d)}`}
function monthDays(y,m){return new Date(y,m+1,0).getDate()}
function monthCal(id,y,m,mini=false){let h=habitById(id),head=(new Date(y,m,1).getDay()+6)%7;let cells=[];if(!mini)cells.push(...WEEK.map(w=>`<span class="week-name">${w}</span>`));for(let i=0;i<head;i++)cells.push(`<span class="outside"></span>`);for(let day=1;day<=monthDays(y,m);day++){let date=mkDate(y,m,day),lev=intensity(h,getVal(getDay(date),h));cells.push(mini?`<button class="level${lev}" title="${date}" data-action="open-day" data-date="${date}" aria-label="Ouvrir le ${day} ${MONTHS[m]}"></button>`:`<button class="calendar-day level${lev} ${date===today()?'today':''}" title="${esc(date)} : ${getVal(getDay(date),h)}" data-action="open-day" data-date="${date}">${day}</button>`)}return `<div class="${mini?'year-mini-grid':'day-grid'}">${cells.join('')}</div>`}
function yearGrid(id,y){let h=habitById(id),before=(new Date(y,0,1).getDay()+6)%7,days=((y%4===0&&y%100!==0)||y%400===0)?366:365;let out=[];for(let n=0;n<before;n++)out.push('<span class="year-heat-cell outside"></span>');for(let k=0;k<days;k++){let d=new Date(y,0,k+1),date=mkDate(d.getFullYear(),d.getMonth(),d.getDate()),v=getVal(getDay(date),h);out.push(`<button class="year-heat-cell level${intensity(h,v)}" data-action="open-day" data-date="${date}" title="${date} : ${v}" aria-label="${date}, valeur ${v}"></button>`)}return `<div class="year-heat-wrap"><div class="year-heat-grid">${out.join('')}</div></div>`}
function heatKey(){return `<div class="heat-key"><span><i class="swatch level0"></i> Non renseigné</span><span><i class="swatch level1"></i> Faible</span><span><i class="swatch level2"></i> Moyen</span><span><i class="swatch level3"></i> Élevé / effectué</span></div>`}
function moveCalendar(delta){if(calendarView==='year'){calendarYear+=delta}else{calendarMonth+=delta;if(calendarMonth<0){calendarMonth=11;calendarYear--}if(calendarMonth>11){calendarMonth=0;calendarYear++}}render()}
function renderCalendar(){let habits=allHabits(),sel=habits.find(h=>h.id===calendarHabit)||habits[0];return `<p class="eyebrow2">CALENDRIERS</p><h1 class="page-title">Ma régularité</h1><p class="page-sub">Calendriers mensuels et annuels, par habitude ou tous ensemble.</p><div class="card"><div class="section-actions"><div class="segment full"><button class="${calendarMode==='one'?'active':''}" data-action="cal-mode" data-value="one">Individuel</button><button class="${calendarMode==='all'?'active':''}" data-action="cal-mode" data-value="all">Tous les suivis</button></div><div class="segment full"><button class="${calendarView==='month'?'active':''}" data-action="cal-view" data-value="month">Mois</button><button class="${calendarView==='year'?'active':''}" data-action="cal-view" data-value="year">Année</button></div></div>${calendarMode==='one'?`<div class="field"><label>Habitude affichée</label><select data-change="calendar-habit">${habits.map(h=>`<option value="${esc(h.id)}" ${h.id===sel.id?'selected':''}>${esc(h.name)}${h.archived?' (archivée)':''}</option>`).join('')}</select></div>`:''}<div class="date-controls"><button class="circle-btn" data-action="cal-shift" data-delta="-1">${ico('back',17)}</button><strong>${calendarView==='month'?monthTitle(calendarYear,calendarMonth):calendarYear}</strong><button class="circle-btn" data-action="cal-shift" data-delta="1">${ico('forward',17)}</button></div>${calendarMode==='one'?(calendarView==='month'?monthCal(sel.id,calendarYear,calendarMonth):yearGrid(sel.id,calendarYear)):habits.map(h=>`<div class="all-calendar"><div class="split"><h3>${esc(h.name)}${h.archived?' <span class="tiny">(archivée)</span>':''}</h3><span class="pill neutral">${number(rangeTotal(h,calendarYear,calendarMonth,calendarView))} ${esc(h.unit||'')}</span></div>${calendarView==='month'?monthCal(h.id,calendarYear,calendarMonth):`<div class="mini-months">${MONTHS.map((month,m)=>`<div class="mini-month"><h4>${month.slice(0,3).toUpperCase()}</h4>${monthCal(h.id,calendarYear,m,true)}</div>`).join('')}</div>`}</div>`).join('')}${heatKey()}<div class="fine">Les cases vides indiquent « non renseigné », jamais « non effectué ». Appuie sur une journée pour la consulter ou la modifier.</div></div>`}
function rangeTotal(h,y,m,mode){const days=Object.entries(state.days);return days.filter(([d])=>mode==='month'?d.startsWith(`${y}-${pad(m+1)}`):d.startsWith(`${y}-`)).reduce((s,[d,v])=>s+getVal(v,h),0)}
function records(h){let entries=Object.entries(state.days).map(([d,v])=>({date:d,value:getVal(v,h)})).filter(x=>x.value>0).sort((a,b)=>a.date.localeCompare(b.date));const total=entries.reduce((s,x)=>s+x.value,0),days=entries.length;let bestDay=entries.reduce((best,x)=>x.value>best.value?x:best,{date:'',value:0});let months={},years={};for(let e of entries){const m=e.date.slice(0,7),y=e.date.slice(0,4);months[m]=(months[m]||0)+e.value;years[y]=(years[y]||0)+e.value}let bestMonth=Object.entries(months).sort((a,b)=>b[1]-a[1])[0]||['',0];let streak=0,longest=0,last='';for(let x of entries){streak=last&&dayOffset(last,1)===x.date?streak+1:1;longest=Math.max(longest,streak);last=x.date}return {total,days,bestDay,bestMonth,longest,months,years}}
function periodBounds(){if(reportView==='month'){let prefix=`${reportYear}-${pad(reportMonth+1)}`;return {name:monthTitle(reportYear,reportMonth),filter:d=>d.startsWith(prefix)}}if(reportView==='year'){return {name:String(reportYear),filter:d=>d.startsWith(String(reportYear)+'-')}}return {name:'Depuis le début',filter:()=>true}}
function statsInPeriod(h){let bound=periodBounds(),entries=Object.entries(state.days).filter(([d])=>bound.filter(d)),total=entries.reduce((v,[d,val])=>v+getVal(val,h),0),active=entries.filter(([d,v])=>getVal(v,h)>0).length;return {total,active,entries}}
function periodChart(h){let data=[];if(reportView==='all'){let yrs=new Set(Object.keys(state.days).map(d=>d.slice(0,4)));yrs.add(String(new Date().getFullYear()));let years=[...yrs].sort();for(let y of years)data.push({label:y,v:Object.entries(state.days).filter(([d])=>d.startsWith(y)).reduce((s,[d,v])=>s+getVal(v,h),0)})}else{let y=reportYear;if(reportView==='month'){for(let i=5;i>=0;i--){let d=new Date(y,reportMonth-i,1),year=d.getFullYear(),month=d.getMonth();data.push({label:MONTHS[month].slice(0,3),v:rangeTotal(h,year,month,'month')})}}else for(let i=0;i<12;i++)data.push({label:MONTHS[i].slice(0,3),v:rangeTotal(h,y,i,'month')})}let max=Math.max(1,...data.map(x=>x.v));return `<div class="bar-chart">${data.map(x=>`<div class="bar-item"><span class="bar-val">${number(x.v)}</span><div class="bar-rect ${x.v?'':'zero'}" style="height:${Math.max(2,x.v/max*122)}px"></div><div class="bar-label">${esc(x.label)}</div></div>`).join('')}</div>`}
function prayerBreakdown(){let f=periodBounds().filter,entries=Object.entries(state.days).filter(([d])=>f(d));let result={ontime:0,late:0,mosque:0,group:0,home:0,solo:0,per:{}};for(let p of PRAYERS)result.per[p]=0;for(let [date,d] of entries){for(let p of PRAYERS){let r=d.prayers?.[p];if(!r?.status)continue;result.per[p]++;if(r.status==='ontime')result.ontime++;if(r.status==='late')result.late++;if(r.place==='mosque')result.mosque++;if(r.place==='home')result.home++;if(r.group==='group')result.group++;if(r.group==='solo')result.solo++}}return result}
function renderReports(){const all=allHabits(),h=habitById(reportMetric)||all[0],p=statsInPeriod(h),r=records(h),bound=periodBounds(),pr=prayerBreakdown(),prev=reportView==='month'?rangeTotal(h,reportMonth===0?reportYear-1:reportYear,reportMonth===0?11:reportMonth-1,'month'):reportView==='year'?Object.entries(state.days).filter(([d])=>d.startsWith((reportYear-1)+'-')).reduce((s,[d,v])=>s+getVal(v,h),0):null,delta=prev===null?null:prev===0?(p.total===0?'0 %':'Nouvelle activité'):`${p.total-prev>0?'+':''}${Math.round((p.total-prev)/prev*100)} %`;return `<p class="eyebrow2">BILANS</p><h1 class="page-title">Mon évolution</h1><p class="page-sub">Statistiques, graphiques, comparaisons et records depuis le premier jour.</p><div class="card"><div class="segment full"><button class="${reportView==='month'?'active':''}" data-action="report-view" data-value="month">Mois</button><button class="${reportView==='year'?'active':''}" data-action="report-view" data-value="year">Année</button><button class="${reportView==='all'?'active':''}" data-action="report-view" data-value="all">Tout</button></div><div class="section-actions">${reportView!=='all'?`<button class="circle-btn" data-action="report-shift" data-delta="-1">${ico('back',17)}</button><strong>${esc(bound.name)}</strong><button class="circle-btn" data-action="report-shift" data-delta="1">${ico('forward',17)}</button>`:'<strong>Historique complet</strong>'}</div><div class="field"><label>Habitude à analyser</label><select data-change="report-metric">${all.map(x=>`<option value="${esc(x.id)}" ${x.id===h.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="two-grid"><div class="metric"><div class="fine">Total sur la période</div><div class="big-number">${number(p.total)}</div><div class="tiny">${esc(h.unit||'fois')}</div></div><div class="metric"><div class="fine">Jours avec activité</div><div class="big-number">${number(p.active)}</div><div class="tiny">journées renseignées</div></div><div class="metric"><div class="fine">Moyenne par jour actif</div><div class="big-number">${p.active?(p.total/p.active).toLocaleString('fr-FR',{maximumFractionDigits:1}):'0'}</div><div class="tiny">${esc(h.unit||'fois')}</div></div><div class="metric"><div class="fine">Évolution vs période précédente</div><div class="big-number" style="font-size:20px">${delta===null?'—':esc(delta)}</div><div class="tiny">${reportView==='month'?'Mois précédent':reportView==='year'?'Année précédente':'Toutes périodes'}</div></div></div><h2 class="h2">${ico('chart')} Évolution</h2>${periodChart(h)}<h2 class="h2">${ico('trophy')} Mes records</h2><div class="record-list"><div><span>Meilleure journée</span><strong>${number(r.bestDay.value)}${r.bestDay.date?' · '+esc(r.bestDay.date):''}</strong></div><div><span>Meilleur mois</span><strong>${number(r.bestMonth[1])}${r.bestMonth[0]?' · '+esc(r.bestMonth[0]):''}</strong></div><div><span>Plus longue série de jours avec activité</span><strong>${r.longest} jours</strong></div><div><span>Total depuis le début</span><strong>${number(r.total)}</strong></div></div>${h.id==='prayers'?`<h2 class="h2">Détails des prières</h2><div class="two-grid"><div class="metric"><span class="fine">À l’heure</span><div class="big-number">${pr.ontime}</div></div><div class="metric"><span class="fine">En retard</span><div class="big-number">${pr.late}</div></div><div class="metric"><span class="fine">À la mosquée</span><div class="big-number">${pr.mosque}</div></div><div class="metric"><span class="fine">En groupe</span><div class="big-number">${pr.group}</div></div></div><div class="record-list" style="margin-top:10px">${PRAYERS.map(x=>`<div><span>${x}</span><strong>${pr.per[x]} effectuée${pr.per[x]>1?'s':''}</strong></div>`).join('')}</div>`:''}${h.id==='quranPages'?`<div class="notice" style="margin-top:15px">Progression actuelle : <strong>${num(state.settings.quranCurrentPage)}/${num(state.settings.quranTotal)} pages</strong> · Lectures complètes : <strong>${number(totalFinished())}</strong>. Le nombre de pages lues inclut les relectures.</div>`:''}<p class="fine" style="margin-top:18px">Une journée non renseignée n'est pas comptée comme une journée où l'habitude n'a pas été faite. Les moyennes portent sur les jours avec activité.</p></div><div class="card subtle"><h2 class="h3">Comparaison par année</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Année</th><th>Total</th><th>Jours actifs</th></tr></thead><tbody>${[...new Set(Object.keys(state.days).map(d=>d.slice(0,4)).concat(String(new Date().getFullYear())))].sort().reverse().map(y=>{let e=Object.entries(state.days).filter(([d])=>d.startsWith(y+'-'));return `<tr><td>${y}</td><td>${number(e.reduce((s,[date,val])=>s+getVal(val,h),0))}</td><td>${e.filter(([date,val])=>getVal(val,h)>0).length}</td></tr>`}).join('')}</tbody></table></div></div>`}
function renderSettings(){let rec=currentTimes(manualDate);let last=state.settings.lastExportAt?displayDate(state.settings.lastExportAt.slice(0,10)):'Jamais';return `<p class="eyebrow2">PARAMÈTRES</p><h1 class="page-title">Réglages</h1><p class="page-sub">Tout reste sur ton appareil. Aucune synchronisation ni localisation automatique.</p><div class="card"><h2 class="h3">${ico('religion',19)} Mosquée et horaires</h2><p class="fine">${esc(state.settings.mosque)}. Seuls les horaires fournis par la mosquée sont utilisés.</p><div class="notice warning">Aucun horaire n'est calculé automatiquement. Iqama affichée seulement si elle a été explicitement renseignée et confirmée.</div><div class="field"><label>Jour à consulter ou modifier</label><input type="date" data-change="manual-date" value="${esc(manualDate)}"></div><div class="split"><strong>${esc(displayDate(manualDate))}</strong><span class="pill ${rec?'':'neutral'}">${rec?rec.verified?'Horaire confirmé':'À vérifier':'Indisponible'}</span></div><div class="fine" style="margin:8px 0">Modifie uniquement les valeurs provenant de ta mosquée.</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Horaire</th><th>Prière / Chourouq</th><th>Iqama confirmée</th></tr></thead><tbody>${ALL_TIMES.map(p=>`<tr><td><strong>${p}</strong></td><td><input class="control" type="time" style="min-width:105px" data-change="time-cell" data-kind="times" data-prayer="${p}" value="${esc(rec?.times?.[p]||'')}"></td><td>${p==='Chourouk'?'—':`<input class="control" type="time" style="min-width:105px" data-change="time-cell" data-kind="iqama" data-prayer="${p}" value="${esc(rec?.iqama?.[p]||'')}">`}</td></tr>`).join('')}</tbody></table></div><p class="source-alert">Les horaires corrigés à la main seront marqués « Saisie manuelle ». Assure-toi qu'ils proviennent bien de la mosquée.</p><div class="btn-row"><button class="btn outline" data-action="timetable-upload">${ico('upload',16)} Importer JSON / CSV</button><button class="btn" data-action="time-clear">Effacer cette date</button></div><input type="file" id="timetableFile" accept=".json,.csv,application/json,text/csv" class="hidden" data-file="timetable"></div><div class="card"><h2 class="h3">${ico('book',19)} Coran</h2><div class="field"><label>Nombre de pages dans mon exemplaire</label><input type="number" min="1" max="10000" data-change="quran-total" value="${num(state.settings.quranTotal)}"></div><p class="fine">711 pages par défaut. Cette valeur est modifiable si tu changes d'édition.</p></div><div class="card"><h2 class="h3">${ico('bell',19)} Rappels</h2><div class="toggle-row"><div><strong>Rappels à l'ouverture</strong><div class="fine">Habitudes non renseignées et export de sauvegarde</div></div><button class="switch ${state.settings.reminders?'on':''}" data-action="toggle-reminders" aria-pressed="${!!state.settings.reminders}">${state.settings.reminders?'✓':'—'}</button></div><p class="tiny">Aucune notification envoyée quand Istiqama est fermée.</p></div><div class="card"><h2 class="h3">${ico('shield',19)} Sauvegarde locale</h2><p class="fine">Dernier export : <strong>${esc(last)}</strong>. Enregistre régulièrement ton fichier JSON dans Fichiers ou iCloud Drive. Les données Safari peuvent être effacées par le système ou l'utilisateur.</p><div class="btn-row"><button class="btn primary" data-action="export-backup">${ico('download',17)} Exporter JSON</button><button class="btn outline" data-action="backup-upload">${ico('upload',17)} Restaurer JSON</button></div><input id="backupFile" class="hidden" type="file" data-file="backup" accept=".json,application/json"><p class="tiny" style="margin-top:13px">En restaurant, tu peux remplacer toutes les données ou fusionner les dates, avec résolution des valeurs différentes.</p></div><div class="card"><h2 class="h3">Personnalisation</h2><button class="btn block outline" data-action="manage-habits">${ico('habits',17)} Mes habitudes personnalisées</button><p class="tiny" style="margin-top:9px">Archiver conserve l'historique. Supprimer définitivement exige une confirmation.</p></div><div class="notice">Conseil iPhone : ouvre le site dans Safari, puis Partager → Sur l'écran d'accueil et active « Ouvrir comme app web » si proposé.</div>`}
function modalDay(date){let d=getDay(date);let items=allHabits(),p=PRAYERS.map(x=>{let r=d.prayers?.[x];return `${x} : ${r?.status==='ontime'?'à l’heure':r?.status==='late'?'en retard':'non renseignée'}`});return `<div class="modal-top"><div><h2>${esc(displayDate(date))}</h2><p>Historique et corrections sans limite de temps.</p></div><button class="icon-button small" data-action="modal-close">${ico('close',16)}</button></div><div class="record-list">${items.map(h=>`<div><span>${esc(h.name)}${h.archived?' (archivée)':''}</span><strong>${number(getVal(d,h))} ${esc(h.unit||'')}</strong></div>`).join('')}</div><div class="fine" style="margin:12px 0">${p.map(esc).join(' · ')}</div><div class="modal-footer"><button class="btn outline" data-action="edit-day" data-tab="religion" data-date="${date}">Modifier Religion</button><button class="btn primary" data-action="edit-day" data-tab="habits" data-date="${date}">Modifier Habitudes</button></div>`}
function modalAddHabit(category='habits'){return `<div class="modal-top"><div><h2>Nouvelle habitude</h2><p>Un calendrier et un bilan seront créés automatiquement.</p></div><button class="icon-button small" data-action="modal-close">${ico('close',16)}</button></div><form id="habitForm"><div class="field"><label>Nom de l'habitude</label><input name="name" maxlength="70" required placeholder="Ex. : Lecture quotidienne"></div><div class="field"><label>Catégorie</label><select name="category"><option value="habits" ${category==='habits'?'selected':''}>Habitudes</option><option value="religion" ${category==='religion'?'selected':''}>Religion</option></select></div><div class="field"><label>Type de suivi</label><select name="type"><option value="boolean">Case quotidienne (fait / non renseigné)</option><option value="counter">Compteur avec raccourcis</option><option value="number">Quantité personnalisée</option></select></div><div class="field"><label>Unité (facultatif)</label><input name="unit" maxlength="28" placeholder="fois, minutes, pages…"></div><div class="modal-footer"><button class="btn" type="button" data-action="modal-close">Annuler</button><button class="btn primary" type="submit">Créer l'habitude</button></div></form>`}
function modalManage(){let l=state.customHabits;return `<div class="modal-top"><div><h2>Mes habitudes</h2><p>Les habitudes archivées restent visibles dans les calendriers et les bilans.</p></div><button class="icon-button small" data-action="modal-close">${ico('close',16)}</button></div><div class="record-list">${l.length?l.map(h=>`<div style="align-items:center"><div><strong style="color:var(--text)">${esc(h.name)}</strong><div class="tiny">${h.category==='religion'?'Religion':'Habitudes'} · ${h.archived?'Archivée':'Active'}</div></div><div class="btn-row"><button class="btn small" data-action="rename-habit" data-id="${esc(h.id)}" title="Renommer">${ico('edit',14)}</button><button class="btn small" data-action="archive-habit" data-id="${esc(h.id)}" title="Archiver">${ico('archive',14)}</button><button class="btn warn small" data-action="delete-habit" data-id="${esc(h.id)}" title="Supprimer">${ico('trash',14)}</button></div></div>`).join(''):'<div class="empty">Aucune habitude personnalisée.</div>'}</div><div class="modal-footer"><button class="btn primary" data-action="habit-add" data-category="habits">${ico('plus',16)} Ajouter</button></div>`}
function modalNumber(id){let h=habitById(id),val=getVal(getDay(editDate),h);return `<div class="modal-top"><div><h2>${esc(h?.name||'Compteur')}</h2><p>Définir le total exact pour le ${esc(displayDate(editDate))}</p></div><button class="icon-button small" data-action="modal-close">${ico('close',16)}</button></div><form id="countForm"><input type="hidden" name="habit" value="${esc(id)}"><div class="field"><label>Total exact</label><input name="value" type="number" inputmode="numeric" min="0" max="100000000" required value="${num(val)}"></div><div class="modal-footer"><button class="btn" type="button" data-action="modal-close">Annuler</button><button class="btn primary" type="submit">Enregistrer</button></div></form>`}
function modalMerge(){let c=pendingMerge?.conflicts||[];return `<div class="modal-top"><div><h2>Résoudre les conflits</h2><p>${c.length} valeur${c.length>1?'s':''} différente${c.length>1?'s':''} trouvée${c.length>1?'s':''} entre les sauvegardes. Aucune valeur conflictuelle ne sera additionnée automatiquement.</p></div><button class="icon-button small" data-action="modal-close">${ico('close',16)}</button></div><div class="btn-row" style="margin-bottom:12px"><button class="btn small" data-action="merge-all" data-value="current">Tout conserver</button><button class="btn small" data-action="merge-all" data-value="incoming">Tout importer</button></div><div class="conflict-list">${c.map((x,i)=>`<div class="conflict"><strong style="font-size:12px">${esc(x.path.join(' → '))}</strong><pre>Actuel : ${esc(JSON.stringify(x.current))}</pre><pre>Importé : ${esc(JSON.stringify(x.incoming))}</pre><select class="control" data-change="merge-choice" data-index="${i}"><option value="current" ${x.choice==='current'?'selected':''}>Conserver la valeur actuelle</option><option value="incoming" ${x.choice==='incoming'?'selected':''}>Utiliser la valeur importée</option></select></div>`).join('')}</div><div class="modal-footer"><button class="btn" data-action="modal-close">Annuler</button><button class="btn primary" data-action="merge-confirm">Fusionner avec ces choix</button></div>`}
function showModal(type,args={}){modal={type,...args};renderModal()}
function renderModal(){const root=$('#modalRoot');if(!modal){root.innerHTML='';return}let body='';switch(modal.type){case'day':body=modalDay(modal.date);break;case'habit-add':body=modalAddHabit(modal.category);break;case'manage-habits':body=modalManage();break;case'number':body=modalNumber(modal.id);break;case'merge':body=modalMerge();break;}root.innerHTML=`<div class="modal-backdrop" data-action="backdrop"><div class="modal-panel" role="dialog" aria-modal="true">${body}</div></div>`;root.querySelector('.modal-panel')?.addEventListener('click',e=>e.stopPropagation())}
function render(top=false){if(!state)return;let y=window.scrollY;$('#navigation').innerHTML=navHTML();$('#content').innerHTML=tab==='home'?renderHome():tab==='religion'?renderReligion():tab==='habits'?renderHabits():tab==='calendar'?renderCalendar():tab==='reports'?renderReports():renderSettings();renderModal();window.scrollTo(0,top?0:y)}
function downloadFile(filename,content,mime='application/json'){const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function exportBackup(){const when=new Date().toISOString();state.settings.lastExportAt=when;save();await queue;downloadFile(`Istiqama-sauvegarde-${today()}.json`,JSON.stringify({...state,exportedAt:when,app:'Istiqama'},null,2));toast('Sauvegarde exportée. Conserve le fichier en lieu sûr.');render()}
function sanitizeDay(raw){let d={};if(!isObj(raw))return d;for(let key of ['quranPages','quranFinished','siwak','istighfar','dhikr'])if(num(raw[key]))d[key]=Math.min(num(raw[key]),100000000);if(raw.quranPosition!=null&&Number.isFinite(Number(raw.quranPosition))&&num(raw.quranPosition))d.quranPosition=Math.min(num(raw.quranPosition),10000);for(let k of ['nigelle','floss'])if(raw[k]===true)d[k]=true;if(isObj(raw.prayers)){d.prayers={};for(let p of PRAYERS){let pr=raw.prayers[p];if(!isObj(pr)||!['ontime','late'].includes(pr.status))continue;let r={status:pr.status};if(['mosque','home','other'].includes(pr.place))r.place=pr.place;if(['group','solo'].includes(pr.group))r.group=pr.group;if(validTime(pr.actual))r.actual=pr.actual;d.prayers[p]=r}if(!Object.keys(d.prayers).length)delete d.prayers}if(isObj(raw.custom)){d.custom={};for(let [id,value]of Object.entries(raw.custom).slice(0,500)){if(/^[a-zA-Z0-9_-]{1,100}$/.test(id)&&(value===true||num(value)))d.custom[id]=value===true?true:Math.min(num(value),100000000)}if(!Object.keys(d.custom).length)delete d.custom}return d}
function sanitizeTimes(raw,source='Import du calendrier'){if(!isObj(raw))return null;let tt=isObj(raw.times)?raw.times:raw,iq=isObj(raw.iqama)?raw.iqama:{},times={},iqama={};for(let p of ALL_TIMES)if(validTime(tt[p]||''))times[p]=tt[p];for(let p of PRAYERS){let key='iqama'+p;if(validTime(iq[p]||tt[key]||''))iqama[p]=iq[p]||tt[key]}if(!Object.keys(times).length&&!Object.keys(iqama).length)return null;return {times,iqama,source:String(raw.source||source).slice(0,130),verified:raw.verified===true}}
function normalizeBackup(raw){if(!isObj(raw))throw Error('Fichier JSON incorrect.');if(!isObj(raw.days)||!isObj(raw.prayerTimes))throw Error('Ce fichier n’est pas une sauvegarde complète d’Istiqama.');let out=clone(DEFAULTS);out.createdAt=typeof raw.createdAt==='string'?raw.createdAt:new Date().toISOString();out.savedAt=new Date().toISOString();for(let [date,day]of Object.entries(raw.days).slice(0,25000)){if(isDate(date))out.days[date]=sanitizeDay(day)}for(let [date,rec]of Object.entries(raw.prayerTimes).slice(0,10000)){if(isDate(date)){let x=sanitizeTimes(rec);if(x)out.prayerTimes[date]=x}}if(Array.isArray(raw.customHabits)){const seen=new Set();for(let h of raw.customHabits.slice(0,500)){if(!isObj(h)||!(/^[a-zA-Z0-9_-]{1,100}$/.test(h.id||''))||seen.has(h.id))continue;seen.add(h.id);out.customHabits.push({id:h.id,name:String(h.name||'Sans nom').slice(0,70),category:h.category==='religion'?'religion':'habits',type:['boolean','counter','number'].includes(h.type)?h.type:'boolean',unit:String(h.unit||'fois').slice(0,28),archived:!!h.archived,createdAt:String(h.createdAt||'').slice(0,30)})}}if(isObj(raw.settings)){let s=raw.settings;out.settings={mosque:String(s.mosque||DEFAULTS.settings.mosque).slice(0,120),quranTotal:Math.min(10000,Math.max(1,num(s.quranTotal)||711)),quranCurrentPage:Math.min(10000,num(s.quranCurrentPage)),lastExportAt:typeof s.lastExportAt==='string'?s.lastExportAt:null,reminders:s.reminders!==false};out.settings.quranCurrentPage=Math.min(out.settings.quranCurrentPage,out.settings.quranTotal)}return out}
function mergePreparation(imported){let a={days:state.days,prayerTimes:state.prayerTimes,customHabits:Object.fromEntries(state.customHabits.map(h=>[h.id,h])),settings:state.settings},b={days:imported.days,prayerTimes:imported.prayerTimes,customHabits:Object.fromEntries(imported.customHabits.map(h=>[h.id,h])),settings:imported.settings},conflicts=[];function rec(oldVal,newVal,path){if(oldVal===undefined)return clone(newVal);if(newVal===undefined)return clone(oldVal);if(isObj(oldVal)&&isObj(newVal)){let o={};for(let k of new Set([...Object.keys(oldVal),...Object.keys(newVal)])){if(k==='__proto__'||k==='constructor'||k==='prototype')continue;o[k]=rec(oldVal[k],newVal[k],path.concat(k))}return o}if(JSON.stringify(oldVal)===JSON.stringify(newVal))return clone(oldVal);conflicts.push({path,current:oldVal,incoming:newVal,choice:'current'});return clone(oldVal)}let merged=rec(a,b,[]);return {merged,conflicts}}
function restoreMerge(plan){let out=clone(state),merged=clone(plan.merged);for(let conflict of plan.conflicts){if(conflict.choice!=='incoming')continue;let ptr=merged;for(let part of conflict.path.slice(0,-1))ptr=ptr[part];ptr[conflict.path.at(-1)]=clone(conflict.incoming)}out.days=merged.days;out.prayerTimes=merged.prayerTimes;out.settings=merged.settings;out.customHabits=Object.values(merged.customHabits);state=normalizeBackup(out);save();modal=null;pendingMerge=null;setTab('home');toast('Sauvegardes fusionnées ; bilans recalculés.')}
function parseCSV(text){let lines=[],row=[],cur='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){cur+='"';i++}else if(c==='"')quoted=false;else cur+=c}else if(c==='"')quoted=true;else if(c===','||c===';' ){row.push(cur.trim());cur=''}else if(c==='\n'){row.push(cur.trim());if(row.some(x=>x))lines.push(row);row=[];cur=''}else if(c!=='\r')cur+=c}row.push(cur.trim());if(row.some(x=>x))lines.push(row);if(!lines.length)return [];let header=lines.shift().map(x=>x.replace(/^\uFEFF/,'').trim());return lines.map(row=>Object.fromEntries(header.map((col,i)=>[col,row[i]||''])))}
function readTimetable(text,filename){let json=filename.toLowerCase().endsWith('.csv')?parseCSV(text):JSON.parse(text),data={};let input=Array.isArray(json)?json:isObj(json)?json.records||json.entries||json.prayerTimes||json:null;if(!input)throw Error('Format de calendrier non reconnu.');if(Array.isArray(input)){for(let obj of input){if(!isObj(obj))continue;let date=obj.date||obj.Date||obj.jour;let v=sanitizeTimes(obj,'Import de la mosquée');if(isDate(date)&&v)data[date]=v}}else if(isObj(input)){for(let [date,raw]of Object.entries(input)){let v=sanitizeTimes(raw,'Import de la mosquée');if(isDate(date)&&v)data[date]=v}}return data}
async function handleFile(e){const type=e.target.dataset.file,file=e.target.files?.[0];if(!file)return;try{let text=await file.text();if(type==='backup'){let raw=JSON.parse(text),incoming=normalizeBackup(raw);let mode=window.confirm('RESTAURATION ISTIQAMA\n\nOK : FUSIONNER la sauvegarde avec tes données actuelles.\nAnnuler : choisir éventuellement de REMPLACER toutes les données.');if(mode){let plan=mergePreparation(incoming);if(!plan.conflicts.length){pendingMerge=plan;restoreMerge(plan)}else{pendingMerge=plan;showModal('merge')}}else if(window.confirm('REMPLACER définitivement les données actuelles par cette sauvegarde ? Exporte d’abord l’historique actuel si tu veux le conserver.')){state=incoming;save();modal=null;setTab('home');toast('Sauvegarde restaurée.')} }else{let records=readTimetable(text,file.name),dates=Object.keys(records);if(!dates.length)throw Error('Aucune journée valide trouvée.');const conflicts=dates.filter(d=>state.prayerTimes[d]&&JSON.stringify(state.prayerTimes[d].times)!==JSON.stringify(records[d].times));let replace=conflicts.length?window.confirm(`${dates.length} dates trouvées, dont ${conflicts.length} déjà présentes avec des horaires différents.\n\nOK : remplacer les horaires des dates en conflit.\nAnnuler : conserver les horaires déjà présents et ajouter seulement les dates absentes.`):false;let added=0,updated=0;for(let date of dates){if(!state.prayerTimes[date]){state.prayerTimes[date]=records[date];added++}else if(replace){state.prayerTimes[date]=records[date];updated++}}save();render();toast(`${added} dates ajoutées, ${updated} remplacées.`)}}catch(err){console.error(err);window.alert(`Import impossible : ${err.message}`)}finally{e.target.value=''}}
function confirmQuranFinish(){if(!window.confirm('Confirmer une lecture complète du Coran ? La position actuelle repartira à 0, mais le total de pages lues sera conservé.'))return;let d=mutableDay(editDate);d.quranFinished=num(d.quranFinished)+1;d.quranPosition=0;if(editDate===today())state.settings.quranCurrentPage=0;save();render();toast('Lecture complète enregistrée.');}
function showDay(date){if(!isDate(date))return;showModal('day',{date})}
function updateTime(kind,p,val){if(val&&!validTime(val)){toast('Format horaire incorrect.');render();return}let rec=state.prayerTimes[manualDate]||{times:{},iqama:{},source:'Saisie manuelle de la mosquée',verified:true};rec.times||={};rec.iqama||={};if(val)rec[kind][p]=val;else delete rec[kind][p];rec.source='Saisie manuelle de la mosquée';rec.verified=true;if(!Object.keys(rec.times).length&&!Object.keys(rec.iqama).length)delete state.prayerTimes[manualDate];else state.prayerTimes[manualDate]=rec;save();render()}
function clickHandler(e){const btn=e.target.closest('[data-action]');if(!btn)return;const a=btn.dataset.action;let id=btn.dataset.habit;if(a==='backdrop'){if(e.target===btn){modal=null;renderModal()}return}if(a==='modal-close'){modal=null;pendingMerge=null;renderModal();return}switch(a){case'nav':setTab(btn.dataset.tab);break;case'date-shift':editDate=dayOffset(editDate,Number(btn.dataset.delta));render();break;case'pick-day':{const v=window.prompt('Date à ouvrir (AAAA-MM-JJ)',editDate);if(v){if(isDate(v)){editDate=v;render()}else toast('Date invalide.')}break}case'nudge':nudge(id,Number(btn.dataset.value));break;case'toggle':{let h=habitById(id);changeValue(id,!getVal(getDay(editDate),h));break}case'set-count':showModal('number',{id});break;case'expand-prayer':expandedPrayer=expandedPrayer===btn.dataset.prayer?null:btn.dataset.prayer;render();break;case'finish-quran':confirmQuranFinish();break;case'habit-add':showModal('habit-add',{category:btn.dataset.category});break;case'manage-habits':showModal('manage-habits');break;case'cal-mode':calendarMode=btn.dataset.value;render();break;case'cal-view':calendarView=btn.dataset.value;render();break;case'cal-shift':moveCalendar(Number(btn.dataset.delta));break;case'open-day':showDay(btn.dataset.date);break;case'edit-day':editDate=btn.dataset.date;modal=null;setTab(btn.dataset.tab);break;case'report-view':reportView=btn.dataset.value;render();break;case'report-shift':{let dx=Number(btn.dataset.delta);if(reportView==='year')reportYear+=dx;else if(reportView==='month'){reportMonth+=dx;if(reportMonth<0){reportMonth=11;reportYear--}if(reportMonth>11){reportMonth=0;reportYear++}}render();break}case'toggle-reminders':state.settings.reminders=!state.settings.reminders;save();render();break;case'timetable-upload':$('#timetableFile')?.click();break;case'backup-upload':$('#backupFile')?.click();break;case'export-backup':exportBackup();break;case'time-clear':if(window.confirm(`Effacer tous les horaires du ${displayDate(manualDate)} ?`)){delete state.prayerTimes[manualDate];save();render()}break;case'archive-habit':{let h=state.customHabits.find(x=>x.id===btn.dataset.id);if(h){h.archived=!h.archived;save();renderModal();render();toast(h.archived?'Habitude archivée.':'Habitude réactivée.')}break}case'rename-habit':{let h=state.customHabits.find(x=>x.id===btn.dataset.id);if(h){let s=window.prompt('Nouveau nom',h.name);if(s?.trim()){h.name=s.trim().slice(0,70);save();render();renderModal()}}break}case'delete-habit':{let h=state.customHabits.find(x=>x.id===btn.dataset.id);if(h&&window.confirm(`Supprimer définitivement « ${h.name} » et toutes ses données historiques ? Cette action est irréversible sans ancienne sauvegarde.`)){state.customHabits=state.customHabits.filter(x=>x.id!==h.id);for(let d of Object.values(state.days))if(d.custom)delete d.custom[h.id];save();render();renderModal();toast('Habitude et historique supprimés.')}break}case'merge-all':if(pendingMerge){pendingMerge.conflicts.forEach(x=>x.choice=btn.dataset.value);renderModal()}break;case'merge-confirm':if(pendingMerge)restoreMerge(pendingMerge);break;default:break}}
function changeHandler(e){let el=e.target;let a=el.dataset.change;switch(a){case'prayer':prayerSet(el.dataset.prayer,el.dataset.field,el.value);break;case'quran-pages':changeValue('quranPages',el.value);break;case'quran-position':touchPage('quranPosition',el.value);break;case'calendar-habit':calendarHabit=el.value;render();break;case'report-metric':reportMetric=el.value;render();break;case'manual-date':if(isDate(el.value)){manualDate=el.value;render()}break;case'time-cell':updateTime(el.dataset.kind,el.dataset.prayer,el.value);break;case'quran-total':{let v=num(el.value);if(v<1||v>10000){toast('Le nombre de pages doit être compris entre 1 et 10 000.');render();break}state.settings.quranTotal=v;state.settings.quranCurrentPage=Math.min(v,num(state.settings.quranCurrentPage));save();render();break}case'merge-choice':if(pendingMerge)pendingMerge.conflicts[Number(el.dataset.index)].choice=el.value;break}}
function submitHandler(e){if(e.target.id==='habitForm'){e.preventDefault();let fd=new FormData(e.target),name=String(fd.get('name')||'').trim().slice(0,70),category=fd.get('category')==='religion'?'religion':'habits',type=['boolean','counter','number'].includes(fd.get('type'))?fd.get('type'):'boolean',unit=String(fd.get('unit')||'').trim().slice(0,28);if(!name){toast('Nom de l’habitude obligatoire.');return}let id=(crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random().toString(36).slice(2));state.customHabits.push({id,name,category,type,unit:unit||(type==='boolean'?'jours':type==='number'?'unités':'fois'),archived:false,createdAt:new Date().toISOString()});modal=null;save();setTab(category==='religion'?'religion':'habits');toast('Habitude créée avec son calendrier et son bilan.')}else if(e.target.id==='countForm'){e.preventDefault();let fd=new FormData(e.target),id=String(fd.get('habit')||''),val=Number(fd.get('value'));if(!Number.isSafeInteger(val)||val<0||val>100000000){toast('Saisis un nombre entier valide.');return}modal=null;changeValue(id,val);toast('Compteur mis à jour.')}}
async function initialize(){db=await openDB();let loaded=await readStorage();try{state=loaded?normalizeBackup(loaded):clone(DEFAULTS)}catch(e){console.warn(e);state=clone(DEFAULTS)}if(!state.createdAt)state.createdAt=new Date().toISOString();if(!Object.keys(state.prayerTimes).length){try{let r=await fetch('mosque_times.json');if(r.ok){let j=await r.json();for(let [date,raw]of Object.entries(j.records||{})){if(isDate(date)){let result=sanitizeTimes({...raw,source:j.source,verified:false},'MAWAQIT vidéo');if(result)state.prayerTimes[date]=result}}}}catch(err){console.warn('Calendrier intégré indisponible',err)}}save();render(true);$('#settingsBtn').addEventListener('click',()=>setTab('settings'));document.addEventListener('click',clickHandler);document.addEventListener('change',changeHandler);document.addEventListener('change',e=>{if(e.target.dataset.file)handleFile(e)});document.addEventListener('submit',submitHandler);if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('sw.js').catch(err=>console.warn(err))}
initialize().catch(err=>{console.error(err);$('#content').innerHTML=`<div class="notice warning">L'application ne s'est pas initialisée : ${esc(err.message)}.</div>`});
